(()=>{'use strict';const root=document.documentElement;root.classList.add('shseq-js');const reduceMotion=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;const selectors=['[data-storyboard-live-header]','[data-shseq-theme-header]','.elementor-location-header','[data-elementor-type="header"]','header#site-header','#site-header.site-header','header.site-header','.site-header','header[role="banner"]',];const state={header:null,observer:null,timer:null,released:false};const findHeader=()=>{for(const selector of selectors){const node=document.querySelector(selector);if(node instanceof HTMLElement)return node;}return null;};const prepareHeader=()=>{if(state.released||reduceMotion)return false;if(state.header&&state.header.isConnected)return true;const header=findHeader();if(!header)return false;state.header=header;const position=window.getComputedStyle(header).position||'static';header.dataset.shseqPreflightPosition=position;if(!['fixed','sticky'].includes(position))header.classList.add('shseq-theme-header--preflight-pinned');return true;};const release=()=>{if(state.released)return;state.released=true;root.classList.remove('shseq-theme-header-preflight');if(state.timer){window.clearTimeout(state.timer);state.timer=null;}if(state.observer){state.observer.disconnect();state.observer=null;}if(state.header){state.header.classList.remove('shseq-theme-header--preflight-pinned');delete state.header.dataset.shseqPreflightPosition;}};state.release=release;window.__shseqThemeHeaderPreflight=state;if(reduceMotion)return;root.classList.add('shseq-theme-header-preflight');prepareHeader();if(!state.header&&typeof MutationObserver==='function'){state.observer=new MutationObserver(()=>{if(prepareHeader()&&state.observer){state.observer.disconnect();state.observer=null;}});state.observer.observe(document.documentElement,{childList:true,subtree:true});}state.timer=window.setTimeout(release,30000);})();
